import sys

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        R = int(input[index])
        C = int(input[index + 1])
        X = int(input[index + 2])
        index += 3
        A = []
        for _ in range(R):
            A.append(list(map(int, input[index:index + C])))
            index += C
        B = []
        for _ in range(R):
            B.append(list(map(int, input[index:index + C])))
            index += C

        def check():
            for i in range(R):
                for j in range(C - X + 1):
                    diff = B[i][j] - A[i][j]
                    if not all(B[i][k] - A[i][k] == diff for k in range(j, j + X)):
                        return False

            for j in range(C):
                for i in range(R - X + 1):
                    diff = B[i][j] -A[i][j]
                    if not all(B[k][j] - A[k][j] == diff for k in range(i, i + X)):
                        return False
            return True

        results.append("Yes" if check() else "No")

    for result in results:
        print(result)

main()
